SELECT EXISTS (
  SELECT 1
  FROM campaign_audience_export
  WHERE workspace_id = #{workspaceId}
    AND campaign_id = #{campaignId}
    AND snapshot_id = #{snapshotId}
    AND connector = #{connector}
    AND (
      status IN ('draft', 'running', 'completed', 'needs_reconciliation')
      OR (status = 'failed' AND pushed_count > 0)
    )
)

